import Foundation

let filePath = "<tmp>"

let contents = try! String(contentsOfFile: filePath, encoding: .utf8)
let lines = contents.components(separatedBy: "\n").filter { !$0.trimmingCharacters(in: .whitespaces).isEmpty }

var levelCounts: [String: Int] = [:]
var errorComponentCounts: [String: Int] = [:]
var errorMessages: Set<String> = []
var hourCounts: [String: Int] = [:]

for line in lines {
    guard let openBracket = line.firstIndex(of: "[") else { continue }
    guard let closeBracket = line.firstIndex(of: "]") else { continue }

    let timestamp = line[line.index(after: openBracket)..<closeBracket]
    let hourStr = String(timestamp.dropFirst(11).prefix(2))

    let rest = line[line.index(after: closeBracket)...].trimmingCharacters(in: .whitespaces)

    guard let spaceIdx = rest.firstIndex(of: " ") else { continue }
    let level = String(rest[rest.startIndex..<spaceIdx])

    let afterLevel = rest[rest.index(after: spaceIdx)...].trimmingCharacters(in: .whitespaces)

    guard let openParen = afterLevel.firstIndex(of: "(") else { continue }
    guard let closeParen = afterLevel.firstIndex(of: ")") else { continue }
    let component = String(afterLevel[afterLevel.index(after: openParen)..<closeParen])

    let afterComponent = afterLevel[afterLevel.index(after: closeParen)...].trimmingCharacters(in: .whitespaces)

    guard afterComponent.hasPrefix("- ") else { continue }
    let message = String(afterComponent.dropFirst(2))

    levelCounts[level, default: 0] += 1
    hourCounts[hourStr, default: 0] += 1

    if level == "ERROR" {
        errorComponentCounts[component, default: 0] += 1
        errorMessages.insert(message)
    }
}

print("=== Log Analysis ===")
print("")
print("Entries by Level:")
for level in levelCounts.keys.sorted() {
    print("  \(level): \(levelCounts[level]!)")
}
print("")

if let maxComp = errorComponentCounts.max(by: { $0.value < $1.value }) {
    print("Component with Most Errors: \(maxComp.key) (\(maxComp.value) errors)")
}
print("")

print("Unique Error Messages:")
for msg in errorMessages.sorted() {
    print("  - \(msg)")
}
print("")

if let maxHour = hourCounts.max(by: { $0.value < $1.value }) {
    print("Busiest Hour: \(maxHour.key):00 (\(maxHour.value) entries)")
}

