    const result: unknown[] = [];
    for (const item of [...a, ...b]) {
      const key = JSON.stringify(item);
      if (!seen.has(key)) {
        seen.add(key);
        result.push(item);
      }
    }
    return result;
  }
  return b;
}

function sortedStringify(obj: unknown, indent: number): string {
  const pad = ' '.repeat(indent);
  const innerPad = ' '.repeat(indent + 2);

  if (obj === null) return 'null';
  if (typeof obj === 'string') return JSON.stringify(obj);
  if (typeof obj === 'number' || typeof obj === 'boolean') return String(obj);

  if (Array.isArray(obj)) {
    if (obj.length === 0) return '[]';
    const items: string[] = [];
    for (const item of obj) {
      items.push(innerPad + sortedStringify(item, indent + 2));
    }
    return '[\n' + items.join(',\n') + '\n' + pad + ']';
  }

  if (typeof obj === 'object') {
    const entries = Object.entries(obj as Record<string, unknown>).sort(([a], [b]) =>
      a < b ? -1 : a > b ? 1 : 0
    );
    if (entries.length === 0) return '{}';
    const items: string[] = [];
    for (const [k, v] of entries) {
      items.push(innerPad + JSON.stringify(k) + ': ' + sortedStringify(v, indent + 2));
    }
    return '{\n' + items.join(',\n') + '\n' + pad + '}';
  }

  return String(obj);
}

