    nodes = data["nodes"]
    edges = data["edges"]

    adj = {node: [] for node in nodes}
    for edge in edges:
        u = edge["from"]
        v = edge["to"]
        w = edge["weight"]
        adj[u].append((v, w))
        adj[v].append((u, w))

    INF = float('inf')
    dist = {node: INF for node in nodes}
    dist["A"] = 0

    pq = [(0, "A")]
    visited = set()

    while pq:
        d, u = heapq.heappop(pq)
        if u in visited:
