use std::collections::BTreeMap;
use std::fs;

fn format_number_with_commas(n: i64) -> String {
    let s = n.to_string();
    let (sign, digits) = if s.starts_with('-') {
        ("-", &s[1..])
    } else {
        ("", s.as_str())
    };
    let mut result = String::new();
    let len = digits.len();
    for (i, c) in digits.char_indices() {
        if i > 0 && (len - i) % 3 == 0 {
            result.push(',');
        }
        result.push(c);
    }
    format!("{}{}", sign, result)
}

fn format_money_2dp(n: f64) -> String {
    let int_part = n as i64;
    let frac_part = ((n - int_part as f64) * 100.0).round() as i64;
    let int_str = format_number_with_commas(int_part);
    format!("${},{:02}", int_str, frac_part)
}

fn format_money_int(n: i64) -> String {
    format!("${}", format_number_with_commas(n))
}

fn main() {
    let path = "<tmp>";
    let content = fs::read_to_string(path).expect("Failed to read file");

    let mut lines = content.lines();
    let _header = lines.next().unwrap();

    let mut employees: Vec<(String, String, f64)> = Vec::new();

    for line in lines {
        let line = line.trim();
        if line.is_empty() {
            continue;
        }
        let fields: Vec<&str> = line.split(',').collect();
        if fields.len() >= 6 {
            let name = fields[1].trim().to_string();
            let department = fields[2].trim().to_string();
            let salary: f64 = fields[3].trim().parse().expect("Failed to parse salary");
            employees.push((name, department, salary));
        }
    }

    let mut dept_salaries: BTreeMap<String, Vec<f64>> = BTreeMap::new();
    let mut total_budget: f64 = 0.0;
    let mut highest_paid: (String, f64) = (String::new(), f64::NEG_INFINITY);

    for (name, dept, salary) in &employees {
        dept_salaries.entry(dept.clone()).or_insert_with(Vec::new).push(*salary);
        total_budget += salary;
        if *salary > highest_paid.1 {
            highest_paid = (name.clone(), *salary);
        }
    }

    println!("=== Salary Report ===");
    println!();
    println!("Average Salary by Department:");
    for (dept, salaries) in &dept_salaries {
        let avg = salaries.iter().sum::<f64>() / salaries.len() as f64;
        println!("  {}: {}", dept, format_money_2dp(avg));
    }
    println!();
    println!("Highest Paid: {} ({})", highest_paid.0, format_money_int(highest_paid.1 as i64));
    println!();
    println!("Departments with >2 employees:");
    for (dept, salaries) in &dept_salaries {
        if salaries.len() > 2 {
            println!("  {} ({} employees)", dept, salaries.len());
        }
    }
    println!();
    println!("Total Budget: {}", format_money_int(total_budget as i64));
}

