use std::collections::BTreeMap;
use std::fs;

fn format_number_with_commas(n: i64) -> String {
    let s = n.to_string();
    let (sign, digits) = if s.starts_with('-') {
        ("-", &s[1..])
    } else {
        ("", s.as_str())
    };
    let mut result = String::new();
    let len = digits.len();
    for (i, c) in digits.char_indices() {
        if i > 0 && (len - i) % 3 == 0 {
            result.push(',');
        }
        result.push(c);
    }
    format!("{}{}", sign, result)
}

fn format_money_2dp(n: f64) -> String {
    let int_part = n as i64;
    let frac_part = ((n - int_part as f64) * 100.0).round() as i64;
    let int_str = format_number_with_commas(int_part);
    format!("${}.{:02}", int_str, frac_part)
}

fn format_money_int(n: i64) -> String {
    format!("${}", format_number_with_commas(n))
}

