let json = try! JSONSerialization.jsonObject(with: data) as! [String: Any]

let nodes = json["nodes"] as! [String]
let edges = json["edges"] as! [[String: Any]]

var adjacency: [String: [(String, Int)]] = [:]
for node in nodes {
    adjacency[node] = []
}

for edge in edges {
    let from = edge["from"] as! String
    let to = edge["to"] as! String
    let weightVal = edge["weight"] as! Any
    let weight: Int
    if let i = weightVal as? Int {
        weight = i
    } else if let d = weightVal as? Double {
        weight = Int(d)
    } else {
        weight = 0
    }
    adjacency[from]!.append((to, weight))
    adjacency[to]!.append((from, weight))
}

var distances: [String: Int] = [:]
for node in nodes {
    distances[node] = Int.max
}
distances["A"] = 0

var unvisited = Set(nodes)

while !unvisited.isEmpty {
    let current = unvisited.min { distances[$0]! < distances[$1]! }!
    if distances[current]! == Int.max {
        break
    }
    unvisited.remove(current)
    for (neighbor, weight) in adjacency[current]! {
        if unvisited.contains(neighbor) {
            let newDist = distances[current]! + weight
            if newDist < distances[neighbor]! {
                distances[neighbor] = newDist
            }
        }
    }
}

print("=== Shortest Paths from A ===")
