import Foundation

enum JSONValue: Equatable {
    case null
    case bool(Bool)
    case number(Double)
    case string(String)
    case array([JSONValue])
    case object([String: JSONValue])
}

func parseAny(_ value: Any) -> JSONValue {
    if value is NSNull {
        return .null
    }
    if let num = value as? NSNumber {
        if CFGetTypeID(num as CFTypeRef) == CFBooleanGetTypeID() {
            return .bool(num.boolValue)
        }
        return .number(num.doubleValue)
    }
    if let s = value as? String {
        return .string(s)
    }
    if let arr = value as? [Any] {
        return .array(arr.map { parseAny($0) })
    }
    if let dict = value as? [String: Any] {
        var result: [String: JSONValue] = [:]
        for (k, v) in dict {
            result[k] = parseAny(v)
        }
        return .object(result)
    }
    return .null
}

func parseJSON(_ data: Data) -> JSONValue {
    guard let obj = try? JSONSerialization.jsonObject(with: data) else {
        return .null
    }
    return parseAny(obj)
}

func merge(_ a: JSONValue, _ b: JSONValue) -> JSONValue {
    switch (a, b) {
    case (.object(let aObj), .object(let bObj)):
        var result: [String: JSONValue] = [:]
        for (k, v) in aObj {
            result[k] = v
        }
        for (k, v) in bObj {
            if let existing = result[k] {
                result[k] = merge(existing, v)
            } else {
                result[k] = v
            }
        }
        return .object(result)
    case (.array(let aArr), .array(let bArr)):
        var seen: [JSONValue] = []
        var result: [JSONValue] = []
        for item in aArr {
            if !seen.contains(item) {
                seen.append(item)
                result.append(item)
            }
        }
        for item in bArr {
            if !seen.contains(item) {
                seen.append(item)
                result.append(item)
            }
        }
        return .array(result)
    default:
        return b
    }
}

func escapeString(_ s: String) -> String {
    var result = "\""
    for char in s {
        switch char {
        case "\"": result += "\\\""
        case "\\": result += "\\\\"
        case "\n": result += "\\n"
        case "\r": result += "\\r"
        case "\t": result += "\\t"
        case "\u{08}": result += "\\b"
        case "\u{0C}": result += "\\f"
        default: result.append(char)
        }
    }
    result += "\""
    return result
}

func serialize(_ value: JSONValue, indent: Int) -> String {
    let pad = String(repeating: " ", count: indent)
    let innerPad = String(repeating: " ", count: indent + 2)

    switch value {
    case .null:
        return "null"
    case .bool(let b):
        return b ? "true" : "false"
    case .number(let n):
        if n == n.rounded() && abs(n) < 1e15 {
            return String(Int64(n))
        }
        return String(n)
    case .string(let s):
        return escapeString(s)
    case .array(let arr):
        if arr.isEmpty {
            return "[]"
        }
        var items: [String] = []
        for item in arr {
            items.append(innerPad + serialize(item, indent: indent + 2))
        }
        return "[\n" + items.joined(separator: ",\n") + "\n" + pad + "]"
    case .object(let obj):
        if obj.isEmpty {
            return "{}"
        }
        let keys = obj.keys.sorted()
        var items: [String] = []
        for key in keys {
            let val = obj[key]!
            items.append(innerPad + escapeString(key) + ": " + serialize(val, indent: indent + 2))
        }
        return "{\n" + items.joined(separator: ",\n") + "\n" + pad + "}"
    }
}

