        char *comp_start = p;
        while (*p && *p != ')') p++;
        if (*p != ')') continue;
        int clen = (int)(p - comp_start);
        if (clen <= 0 || clen > 255) continue;
        char component[256];
        memcpy(component, comp_start, clen);
        component[clen] = '\0';
        p++; /* skip ')' */

        /* Parse message: after " - " */
        while (*p == ' ') p++;
        if (*p == '-' && *(p + 1) == ' ') p += 2;
        else if (*p == '-') p++;
        else p++;

        char *message = p;
        size_t mlen = strlen(message);
        if (mlen > 0 && message[mlen - 1] == '\n') message[--mlen] = '\0';
        if (mlen > 0 && message[mlen - 1] == '\r') message[--mlen] = '\0';

        /* Count level */
        int found = 0;
        for (int i = 0; i < nlevels; i++) {
            if (strcmp(levels[i].name, level) == 0) {
                levels[i].count++;
                found = 1;
                break;
            }
        }
        if (!found) {
            if (nlevels == caplevels) {
                caplevels = caplevels ? caplevels * 2 : 16;
                levels = (NameCount *)realloc(levels, caplevels * sizeof(NameCount));
                if (!levels) return 1;
            }
            levels[nlevels].name = strdup(level);
            levels[nlevels].count = 1;
            nlevels++;
        }

        /* If ERROR, track component and message */
        if (strcmp(level, "ERROR") == 0) {
            found = 0;
            for (int i = 0; i < ncomps; i++) {
                if (strcmp(comps[i].name, component) == 0) {
                    comps[i].count++;
                    found = 1;
                    break;
                }
            }
            if (!found) {
                if (ncomps == capcomps) {
                    capcomps = capcomps ? capcomps * 2 : 16;
                    comps = (NameCount *)realloc(comps, capcomps * sizeof(NameCount));
                    if (!comps) return 1;
                }
                comps[ncomps].name = strdup(component);
                comps[ncomps].count = 1;
                ncomps++;
            }

            found = 0;
            for (int i = 0; i < errmsgs.count; i++) {
                if (strcmp(errmsgs.items[i], message) == 0) {
                    found = 1;
                    break;
                }
            }
            if (!found) {
                if (errmsgs.count == errmsgs.capacity) {
                    errmsgs.capacity = errmsgs.capacity ? errmsgs.capacity * 2 : 16;
                    errmsgs.items = (char **)realloc(errmsgs.items, errmsgs.capacity * sizeof(char *));
                    if (!errmsgs.items) return 1;
                }
                errmsgs.items[errmsgs.count] = strdup(message);
                errmsgs.count++;
            }
        }
    }

    free(line);
    fclose(f);

    /* Sort levels alphabetically */
    qsort(levels, nlevels, sizeof(NameCount), cmp_namecount);

    /* Sort error messages alphabetically */
    qsort(errmsgs.items, errmsgs.count, sizeof(char *), cmp_str);

    /* Find component with most errors (alphabetically first on tie) */
    int maxcomp = 0;
    for (int i = 1; i < ncomps; i++) {
        if (comps[i].count > comps[maxcomp].count ||
            (comps[i].count == comps[maxcomp].count && strcmp(comps[i].name, comps[maxcomp].name) < 0)) {
            maxcomp = i;
        }
    }

    /* Find busiest hour (smallest hour on tie) */
    int maxhour = 0;
    for (int i = 1; i < 24; i++) {
        if (hourcounts[i] > hourcounts[maxhour]) {
            maxhour = i;
        }
    }

    /* Output */
    printf("=== Log Analysis ===\n");
    printf("\n");
    printf("Entries by Level:\n");
    for (int i = 0; i < nlevels; i++) {
        printf("  %s: %d\n", levels[i].name, levels[i].count);
    }
    printf("\n");
    printf("Component with Most Errors: %s (%d errors)\n", comps[maxcomp].name, comps[maxcomp].count);
    printf("\n");
    printf("Unique Error Messages:\n");
    for (int i = 0; i < errmsgs.count; i++) {
        printf("  - %s\n", errmsgs.items[i]);
    }
    printf("\n");
    printf("Busiest Hour: %02d:00 (%d entries)\n", maxhour, hourcounts[maxhour]);

    /* Cleanup */
    for (int i = 0; i < nlevels; i++) free(levels[i].name);
    free(levels);
    for (int i = 0; i < ncomps; i++) free(comps[i].name);
    free(comps);
    for (int i = 0; i < errmsgs.count; i++) free(errmsgs.items[i]);
    free(errmsgs.items);
    free(hourcounts);

    return 0;
}
