use std::io::Read;

enum Json {
    Null,
    Bool(bool),
    Number(f64),
    String(String),
    Array(Vec<Json>),
    Object(Vec<(String, Json)>),
}

impl Json {
    fn equals(&self, other: &Json) -> bool {
        match (self, other) {
            (Json::Null, Json::Null) => true,
            (Json::Bool(a), Json::Bool(b)) => a == b,
            (Json::Number(a), Json::Number(b)) => a == b,
            (Json::String(a), Json::String(b)) => a == b,
            (Json::Array(a), Json::Array(b)) => {
                a.len() == b.len() && a.iter().zip(b.iter()).all(|(x, y)| x.equals(y))
            }
            (Json::Object(a), Json::Object(b)) => {
                if a.len() != b.len() {
                    return false;
                }
                for (ka, va) in a {
                    match b.iter().find(|(kb, _)| kb == ka) {
                        Some((_, vb)) => {
                            if !va.equals(vb) {
                                return false;
                            }
                        }
                        None => return false,
                    }
                }
                true
            }
            _ => false,
        }
    }

    fn merge(a: &Json, b: &Json) -> Json {
        match (a, b) {
            (Json::Object(akv), Json::Object(bkv)) => {
                let mut result: Vec<(String, Json)> = Vec::new();
                for (key, aval) in akv {
                    if let Some((_, bval)) = bkv.iter().find(|(bk, _)| bk == key) {
                        result.push((key.clone(), Json::merge(aval, bval)));
                    } else {
                        result.push((key.clone(), aval.clone()));
                    }
                }
                for (key, bval) in bkv {
                    if !akv.iter().any(|(ak, _)| ak == key) {
                        result.push((key.clone(), bval.clone()));
                    }
                }
                Json::Object(result)
            }
            (Json::Array(aarr), Json::Array(barr)) => {
                let mut result: Vec<Json> = aarr.clone();
                for item in barr {
                    if !result.iter().any(|existing| existing.equals(item)) {
                        result.push(item.clone());
                    }
                }
                Json::Array(result)
            }
            (_, b) => b.clone(),
        }
    }

    fn to_pretty(&self, indent: usize, out: &mut String) {
        let pad = "  ".repeat(indent);
        let pad_inner = "  ".repeat(indent + 1);
        match self {
            Json::Null => out.push_str("null"),
            Json::Bool(b) => out.push_str(if *b { "true" } else { "false" }),
            Json::Number(n) => {
                if n.fract() == 0.0 && n.abs() < 1e15 {
                    out.push_str(&format!("{}", *n as i64));
                } else {
                    out.push_str(&format!("{}", n));
                }
            }
            Json::String(s) => {
                out.push('"');
                for c in s.chars() {
                    match c {
                        '"' => out.push_str("\\\""),
                        '\\' => out.push_str("\\\\"),
                        '\n' => out.push_str("\\n"),
                        '\r' => out.push_str("\\r"),
                        '\t' => out.push_str("\\t"),
                        '\u{08}' => out.push_str("\\b"),
                        '\u{0C}' => out.push_str("\\f"),
                        c if (c as u32) < 0x20 => {
                            out.push_str(&format!("\\u{:04x}", c as u32));
                        }
                        c => out.push(c),
                    }
                }
                out.push('"');
            }
            Json::Array(arr) => {
                if arr.is_empty() {
                    out.push_str("[]");
                } else {
                    out.push_str("[\n");
                    for (i, item) in arr.iter().enumerate() {
                        out.push_str(&pad_inner);
                        item.to_pretty(indent + 1, out);
                        if i + 1 < arr.len() {
                            out.push(',');
                        }
                        out.push('\n');
                    }
                    out.push_str(&pad);
                    out.push(']');
                }
            }
            Json::Object(obj) => {
                if obj.is_empty() {
                    out.push_str("{}");
                } else {
                    let mut sorted: Vec<&(String, Json)> = obj.iter().collect();
                    sorted.sort_by(|a, b| a.0.cmp(&b.0));
                    out.push_str("{\n");
                    for (i, (key, val)) in sorted.iter().enumerate() {
                        out.push_str(&pad_inner);
                        out.push('"');
                        for c in key.chars() {
                            match c {
                                '"' => out.push_str("\\\""),
                                '\\' => out.push_str("\\\\"),
                                '\n' => out.push_str("\\n"),
                                '\r' => out.push_str("\\r"),
                                '\t' => out.push_str("\\t"),
                                '\u{08}' => out.push_str("\\b"),
                                '\u{0C}' => out.push_str("\\f"),
                                c if (c as u32) < 0x20 => {
                                    out.push_str(&format!("\\u{:04x}", c as u32));
                                }
                                c => out.push(c),
                            }
                        }
                        out.push('"');
                        out.push_str(": ");
                        val.to_pretty(indent + 1, out);
                        if i + 1 < sorted.len() {
                            out.push(',');
                        }
                        out.push('\n');
                    }
                    out.push_str(&pad);
                    out.push('}');
                }
            }
        }
    }
}

struct Parser {
    chars: Vec<char>,
    pos: usize,
}

impl Parser {
    fn new(s: &str) -> Self {
        Parser {
            chars: s.chars().collect(),
            pos: 0,
        }
    }

    fn peek(&self) -> Option<char> {
        self.chars.get(self.pos).copied()
    }

    fn advance(&mut self) -> Option<char> {
        let c = self.peek();
        if c.is_some() {
            self.pos += 1;
        }
        c
    }

    fn skip_whitespace(&mut self) {
        while let Some(c) = self.peek() {
            if c == ' ' || c == '\t' || c == '\n' || c == '\r' {
                self.pos += 1;
            } else {
                break;
            }
        }
    }

    fn parse_value(&mut self) -> Json {
        self.skip_whitespace();
        match self.peek() {
            Some('{') => self.parse_object(),
            Some('[') => self.parse_array(),
            Some('"') => Json::String(self.parse_string()),
            Some('t') => {
                self.advance();
                self.advance();
                self.advance();
                self.advance();
                Json::Bool(true)
            }
            Some('f') => {
                self.advance();
                self.advance();
                self.advance();
                self.advance();
                self.advance();
                Json::Bool(false)
            }
            Some('n') => {
                self.advance();
                self.advance();
                self.advance();
                self.advance();
                Json::Null
            }
            _ => self.parse_number(),
        }
    }

    fn parse_object(&mut self) -> Json {
        self.advance(); // {
        let mut entries: Vec<(String, Json)> = Vec::new();
        self.skip_whitespace();
        if self.peek() == Some('}') {
            self.advance();
            return Json::Object(entries);
        }
        loop {
            self.skip_whitespace();
            let key = self.parse_string();
            self.skip_whitespace();
            self.advance(); // :
            let val = self.parse_value();
            entries.push((key, val));
            self.skip_whitespace();
            match self.peek() {
                Some(',') => {
                    self.advance();
                }
                Some('}') => {
                    self.advance();
                    break;
                }
                _ => break,
            }
        }
        Json::Object(entries)
    }

    fn parse_array(&mut self) -> Json {
        self.advance(); // [
        let mut items: Vec<Json> = Vec::new();
        self.skip_whitespace();
        if self.peek() == Some(']') {
            self.advance();
            return Json::Array(items);
        }
        loop {
            let val = self.parse_value();
            items.push(val);
            self.skip_whitespace();
            match self.peek() {
                Some(',') => {
                    self.advance();
                }
                Some(']') => {
                    self.advance();
                    break;
                }
                _ => break,
            }
        }
        Json::Array(items)
    }

    fn parse_string(&mut self) -> String {
        self.advance(); // "
        let mut s = String::new();
        loop {
            match self.advance() {
                Some('"') => break,
                Some('\\') => {
                    match self.advance() {
                        Some('"') => s.push('"'),
                        Some('\\') => s.push('\\'),
                        Some('/') => s.push('/'),
                        Some('n') => s.push('\n'),
                        Some('t') => s.push('\t'),
                        Some('r') => s.push('\r'),
                        Some('b') => s.push('\u{08}'),
                        Some('f') => s.push('\u{0C}'),
                        Some('u') => {
                            let mut hex = String::new();
                            for _ in 0..4 {
                                if let Some(c) = self.advance() {
                                    hex.push(c);
                                }
                            }
                            let code = u32::from_str_radix(&hex, 16).unwrap_or(0);
                            if let Some(ch) = char::from_u32(code) {
                                s.push(ch);
                            }
                        }
                        _ => {}
                    }
                }
                Some(c) => s.push(c),
                None => break,
            }
        }
        s
    }

    fn parse_number(&mut self) -> Json {
        let mut num_str = String::new();
        if self.peek() == Some('-') {
            num_str.push('-');
            self.advance();
        }
        while let Some(c) = self.peek() {
            if c.is_ascii_digit() || c == '.' || c == 'e' || c == 'E' || c == '+' || c == '-' {
                num_str.push(c);
                self.advance();
            } else {
                break;
            }
        }
        let n: f64 = num_str.parse().unwrap_or(0.0);
        Json::Number(n)
    }
}

fn main() {
    let path_a = "<tmp>";
    let path_b = "<tmp>";

    let mut file_a = std::fs::File::open(path_a).expect("Failed to open config_a.json");
    let mut content_a = String::new();
