#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

static char *run_cmd(const char *cmd)
{
    FILE *f = popen(cmd, "r");
    if (!f) {
        char *empty = (char *)malloc(1);
        if (empty) empty[0] = '\0';
        return empty;
    }

    size_t cap = 4096;
    size_t len = 0;
    char *buf = (char *)malloc(cap);
    if (!buf) {
        pclose(f);
        char *empty = (char *)malloc(1);
        if (empty) empty[0] = '\0';
        return empty;
    }

    int c;
    while ((c = fgetc(f)) != EOF) {
        if (len + 1 >= cap) {
            size_t newcap = cap * 2;
            char *nb = (char *)realloc(buf, newcap);
            if (!nb) {
                free(buf);
                pclose(f);
                char *empty = (char *)malloc(1);
                if (empty) empty[0] = '\0';
                return empty;
            }
            buf = nb;
            cap = newcap;
        }
        buf[len++] = (char)c;
    }
    pclose(f);

    while (len > 0 && isspace((unsigned char)buf[len - 1]))
        len--;
    buf[len] = '\0';
    return buf;
}

static void print_json_string(const char *s)
{
    putchar('"');
    for (const unsigned char *p = (const unsigned char *)s; *p; p++) {
        switch (*p) {
        case '"':  fputs("\\\"", stdout); break;
        case '\\': fputs("\\\\", stdout); break;
        case '\b': fputs("\\b",  stdout); break;
        case '\f': fputs("\\f",  stdout); break;
        case '\n': fputs("\\n",  stdout); break;
        case '\r': fputs("\\r",  stdout); break;
        case '\t': fputs("\\t",  stdout); break;
        default:
            if (*p < 0x20)
                printf("\\u%04x", (unsigned int)*p);
            else
                putchar(*p);
            break;
        }
    }
    putchar('"');
}

int main(void)
{
    char *os       = run_cmd("uname -s");
    char *arch     = run_cmd("uname -m");
    char *username = run_cmd("whoami");
    char *hostname = run_cmd("hostname");

    printf("{\n");
    printf("  \"hostname\": ");
    print_json_string(hostname);
    printf(",\n");
    printf("  \"os\": ");
    print_json_string(os);
    printf(",\n");
    printf("  \"architecture\": ");
    print_json_string(arch);
    printf(",\n");
    printf("  \"username\": ");
    print_json_string(username);
    printf("\n}\n");

    free(os);
    free(arch);
    free(username);
    free(hostname);
    return 0;
}

