import java.io.*;
import java.nio.file.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        Path root = Paths.get("<tmp>");

        Map<String, List<String[]>> extMap = new TreeMap<>();

        List<Path> files = new ArrayList<>();
        walkDirectory(root, files);

        for (Path file : files) {
            String relPath = root.relativize(file).toString().replace('\\', '/');
            String ext = getExtension(file.getFileName().toString());

            long charCount = Files.size(file);
            long lineCount = countLines(file);

            extMap.computeIfAbsent(ext, k -> new ArrayList<>())
                  .add(new String[]{relPath, String.valueOf(lineCount), String.valueOf(charCount)});
        }

        for (List<String[]> list : extMap.values()) {
            list.sort(Comparator.comparing(a -> a[0]));
        }

        StringBuilder sb = new StringBuilder();
        sb.append("=== File Tree Analysis ===\n");
        sb.append("\n");

        long totalFiles = 0;
        long totalLines = 0;
        long totalChars = 0;

        for (Map.Entry<String, List<String[]>> entry : extMap.entrySet()) {
            String ext = entry.getKey();
            List<String[]> filesList = entry.getValue();

            long extFiles = filesList.size();
            long extLines = 0;
            long extChars = 0;

            for (String[] f : filesList) {
                extLines += Long.parseLong(f[1]);
                extChars += Long.parseLong(f[2]);
            }

            sb.append("Extension: ").append(ext).append("\n");
            sb.append("  Files: ").append(extFiles).append("\n");
            sb.append("  Total Lines: ").append(extLines).append("\n");
            sb.append("  Total Characters: ").append(extChars).append("\n");

            for (String[] f : filesList) {
                sb.append("    ").append(f[0]).append(": ").append(f[1])
                  .append(" lines, ").append(f[2]).append(" chars\n");
            }

            totalFiles += extFiles;
            totalLines += extLines;
            totalChars += extChars;
        }

        sb.append("\n");
        sb.append("Total: ").append(totalFiles).append(" files, ")
          .append(totalLines).append(" lines, ")
          .append(totalChars).append(" characters\n");

        System.out.print(sb.toString());
    }

    static void walkDirectory(Path dir, List<Path> files) throws IOException {
        try (DirectoryStream<Path> stream = Files.newDirectoryStream(dir)) {
            for (Path entry : stream) {
                if (Files.isSymbolicLink(entry)) {
                    continue;
                }
                if (Files.isDirectory(entry)) {
                    walkDirectory(entry, files);
                } else if (Files.isRegularFile(entry)) {
                    files.add(entry);
                }
            }
        }
    }

    static String getExtension(String filename) {
        int lastDot = filename.lastIndexOf('.');
        if (lastDot > 0) {
            return filename.substring(lastDot);
        }
        return "";
    }

    static long countLines(Path file) throws IOException {
        byte[] bytes = Files.readAllBytes(file);
        if (bytes.length == 0) return 0;

        long lines = 0;
        for (byte b : bytes) {
            if (b == '\n') lines++;
        }
        if (bytes[bytes.length - 1] != '\n') {
            lines++;
        }
        return lines;
    }
}

