use std::path::Path;

fn main() {
    let root = Path::new("<tmp>");

    let mut files: Vec<(String, String, usize, usize)> = Vec::new();

    walk(root, root, &mut files);

    let mut groups: BTreeMap<String, Vec<(String, usize, usize)>> = BTreeMap::new();

    for (rel_path, ext, lines, chars) in &files {
        groups.entry(ext.clone()).or_default().push((rel_path.clone(), *lines, *chars));
    }

    for entry in groups.values_mut() {
        entry.sort_by(|a, b| a.0.cmp(&b.0));
    }

    println!("=== File Tree Analysis ===");
    println!();

    let mut total_files = 0;
    let mut total_lines: usize = 0;
    let mut total_chars: usize = 0;

    for (ext, file_list) in &groups {
        let n_files = file_list.len();
        let ext_lines: usize = file_list.iter().map(|f| f.1).sum();
        let ext_chars: usize = file_list.iter().map(|f| f.2).sum();

        println!("Extension: {}", ext);
        println!("  Files: {}", n_files);
        println!("  Total Lines: {}", ext_lines);
        println!("  Total Characters: {}", ext_chars);

        for (rel_path, lines, chars) in file_list {
            println!("    {}: {} lines, {} chars", rel_path, lines, chars);
        }

        total_files += n_files;
        total_lines += ext_lines;
        total_chars += ext_chars;
    }

    println!();
    println!("Total: {} files, {} lines, {} characters", total_files, total_lines, total_chars);
}

fn walk(root: &Path, dir: &Path, files: &mut Vec<(String, String, usize, usize)>) {
    let entries = match fs::read_dir(dir) {
        Ok(e) => e,
        Err(_) => return,
    };

    for entry in entries.flatten() {
        let path = entry.path();

        if path.is_symlink() {
            continue;
        }

        if path.is_dir() {
            walk(root, &path, files);
        } else if path.is_file() {
            let content = match fs::read(&path) {
                Ok(c) => c,
                Err(_) => continue,
            };

            let chars = content.len();
            let lines = count_lines(&content);

            let rel_path = path
                .strip_prefix(root)
                .unwrap()
                .to_string_lossy()
                .replace('\\', "/");

            let ext = get_extension(&path);

            files.push((rel_path, ext, lines, chars));
        }
    }
}

fn count_lines(content: &[u8]) -> usize {
    if content.is_empty() {
        return 0;
    }
    let mut lines = 0;
    let mut in_line = false;
    for &b in content {
        if b == b'\n' {
            lines += 1;
            in_line = false;
        } else if b != b'\r' {
            in_line = true;
        }
    }
    if in_line {
        lines += 1;
    }
    lines
}

fn get_extension(path: &Path) -> String {
    let file_name = path
        .file_name()
        .and_then(|n| n.to_str())
        .unwrap_or("");

    if let Some(pos) = file_name.rfind('.') {
        if pos > 0 {
            return file_name[pos..].to_string();
        }
    }

    "(none)".to_string()
}

