fn main() {
    let path = "<tmp>";
    let content = fs::read_to_string(path).expect("Failed to read file");

    let nodes = extract_string_array(&content, "nodes");
    let edges = extract_edges(&content);

    let mut adj: HashMap<String, Vec<(String, i64)>> = HashMap::new();
    for node in &nodes {
        adj.entry(node.clone()).or_insert_with(Vec::new);
    }
    for (from, to, weight) in &edges {
        adj.entry(from.clone()).or_default().push((to.clone(), *weight));
        adj.entry(to.clone()).or_default().push((from.clone(), *weight));
    }

    const INF: i64 = i64::MAX;
    let mut dist: HashMap<String, i64> = HashMap::new();
    let mut visited: HashMap<String, bool> = HashMap::new();
    for node in &nodes {
        dist.insert(node.clone(), INF);
        visited.insert(node.clone(), false);
    }
    dist.insert("A".to_string(), 0);

    for _ in 0..nodes.len() {
        let mut min_node: Option<String> = None;
        let mut min_val = INF;
        for node in &nodes {
            if !visited[node] && dist[node] < min_val {
                min_val = dist[node];
                min_node = Some(node.clone());
            }
        }
        let min_node = match min_node {
            Some(n) => n,
            None => break,
        };
        visited.insert(min_node.clone(), true);
        if let Some(neighbors) = adj.get(&min_node) {
            for (neighbor, weight) in neighbors {
                let new_dist = dist[&min_node] + weight;
                if new_dist < dist[neighbor] {
                    dist.insert(neighbor.clone(), new_dist);
                }
            }
        }
    }

    println!("=== Shortest Paths from A ===");
    println!();
    let mut sorted: Vec<&String> = nodes.iter().collect();
    sorted.sort();
