        if d == INF {
            println!("A -> {}: unreachable", node);
        } else {
            println!("A -> {}: {}", node, d);
        }
    }
}

fn extract_string_array(json: &str, key: &str) -> Vec<String> {
    let key_pat = format!("\"{}\"", key);
    let key_idx = json.find(&key_pat).unwrap();
    let after = &json[key_idx + key_pat.len()..];
    let colon_idx = after.find(':').unwrap();
    let after_colon = &after[colon_idx + 1..];
    let bracket_idx = after_colon.find('[').unwrap();
    let after_bracket = &after_colon[bracket_idx + 1..];

    let mut depth = 1;
    let mut end = 0;
    for (i, c) in after_bracket.char_indices() {
        if c == '[' {
            depth += 1;
        } else if c == ']' {
            depth -= 1;
        }
        if depth == 0 {
            end = i;
            break;
        }
    }
    let arr = &after_bracket[..end];

    let mut result = Vec::new();
    let bytes = arr.as_bytes();
    let mut i = 0;
    while i < bytes.len() {
        if bytes[i] == b'"' {
            i += 1;
            let start = i;
            while i < bytes.len() && bytes[i] != b'"' {
                if bytes[i] == b'\\' {
                    i += 1;
                }
                i += 1;
            }
            result.push(arr[start..i].to_string());
            i += 1;
        } else {
            i += 1;
        }
    }
    result
}

fn extract_edges(json: &str) -> Vec<(String, String, i64)> {
    let key_pat = "\"edges\"";
    let key_idx = json.find(key_pat).unwrap();
    let after = &json[key_idx + key_pat.len()..];
    let colon_idx = after.find(':').unwrap();
    let after_colon = &after[colon_idx + 1..];
    let bracket_idx = after_colon.find('[').unwrap();
    let after_bracket = &after_colon[bracket_idx + 1..];

    let mut depth = 1;
    let mut end = 0;
    for (i, c) in after_bracket.char_indices() {
        if c == '[' {
            depth += 1;
        } else if c == ']' {
            depth -= 1;
        }
        if depth == 0 {
            end = i;
            break;
        }
    }
    let arr = &after_bracket[..end];

    let mut edges = Vec::new();
    let bytes = arr.as_bytes();
    let mut i = 0;
    while i < bytes.len() {
        if bytes[i] == b'{' {
            let start = i;
            let mut d = 1;
            i += 1;
            while i < bytes.len() && d > 0 {
                if bytes[i] == b'{' {
                    d += 1;
                } else if bytes[i] == b'}' {
                    d -= 1;
                }
                i += 1;
            }
            let obj = &arr[start..i];
            let from = extract_string_field(obj, "from");
            let to = extract_string_field(obj, "to");
            let weight = extract_int_field(obj, "weight");
            edges.push((from, to, weight));
        } else {
            i += 1;
        }
    }
    edges
}

fn extract_string_field(obj: &str, field: &str) -> String {
    let pat = format!("\"{}\"", field);
    let idx = obj.find(&pat).unwrap();
    let after = &obj[idx + pat.len()..];
    let colon_idx = after.find(':').unwrap();
    let after_colon = &after[colon_idx + 1..];
    let quote_idx = after_colon.find('"').unwrap();
    let after_quote = &after_colon[quote_idx + 1..];
    let end_quote = after_quote.find('"').unwrap();
    after_quote[..end_quote].to_string()
}

fn extract_int_field(obj: &str, field: &str) -> i64 {
    let pat = format!("\"{}\"", field);
    let idx = obj.find(&pat).unwrap();
    let after = &obj[idx + pat.len()..];
    let colon_idx = after.find(':').unwrap();
    let after_colon = &after[colon_idx + 1..];
    let trimmed = after_colon.trim_start();
    let end = trimmed
        .find(|c: char| !c.is_ascii_digit() && c != '-')
        .unwrap_or(trimmed.len());
    trimmed[..end].parse::<i64>().unwrap()
}

