let baseDir = "<tmp>"
let fm = FileManager.default

struct FileInfo {
    let relativePath: String
    let lines: Int
    let chars: Int
}

var files: [String: [FileInfo]] = [:]
var visitedDirs: Set<String> = []

func countLines(_ data: Data) -> Int {
    if data.isEmpty { return 0 }
    var count = 0
    for byte in data {
        if byte == 0x0A { count += 1 }
    }
    if data.last != 0x0A { count += 1 }
    return count
}

func walk(_ dir: String) {
    let dirURL = URL(fileURLWithPath: dir)
    guard let contents = try? fm.contentsOfDirectory(at: dirURL, includingPropertiesForKeys: [.isSymbolicLinkKey, .isDirectoryKey], options: []) else { return }

    for url in contents {
        let values = try? url.resourceValues(forKeys: [.isSymbolicLinkKey, .isDirectoryKey])
        let isSymlink = values?.isSymbolicLink ?? false
        if isSymlink { continue }

        let isDir = values?.isDirectory ?? false

        if isDir {
            let resolved = url.resolvingSymlinksInPath().path
            if !visitedDirs.contains(resolved) {
                visitedDirs.insert(resolved)
                walk(url.path)
            }
        } else {
            let relativePath = String(url.path.dropFirst(baseDir.count + 1))

            guard let data = fm.contents(atPath: url.path) else { continue }
            let charCount = data.count
            let lineCount = countLines(data)

