static void format_comma_int(long val, char *buf) {
    char tmp[32];
    snprintf(tmp, sizeof(tmp), "%ld", val);
    int len = (int)strlen(tmp);
    int pos = 0;
    int first = 1;
    for (int i = 0; i < len; i++) {
        if (first) {
            buf[pos++] = tmp[i];
            first = 0;
        } else {
            int remaining = len - i - 1;
            if (remaining > 0 && remaining % 3 == 0) {
                buf[pos++] = ',';
            }
            buf[pos++] = tmp[i];
        }
    }
    buf[pos] = '\0';
}

static void format_comma_double(double val, char *buf) {
