#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <ctype.h>

typedef enum {
    JSON_NULL,
    JSON_BOOL,
    JSON_NUMBER,
    JSON_STRING,
    JSON_ARRAY,
    JSON_OBJECT
} JSONType;

typedef struct JSONValue JSONValue;

typedef struct {
    char *key;
    JSONValue *value;
} JSONPair;

struct JSONValue {
    JSONType type;
    union {
        int bool_val;
        char *num_str;
        char *str_val;
        struct {
            JSONValue **items;
            size_t count;
            size_t cap;
        } array;
        struct {
            JSONPair *pairs;
            size_t count;
            size_t cap;
        } object;
    } u;
};

/* ---------- Parser ---------- */

typedef struct {
    const char *src;
    size_t pos;
} Parser;

static void skip_ws(Parser *p) {
    while (p->src[p->pos] && isspace((unsigned char)p->src[p->pos]))
        p->pos++;
}

static JSONValue *parse_value(Parser *p);

static JSONValue *new_value(JSONType t) {
    JSONValue *v = (JSONValue *)calloc(1, sizeof(JSONValue));
    v->type = t;
    return v;
}

static JSONValue *parse_number(Parser *p) {
    const char *start = p->src + p->pos;
    while (p->src[p->pos] && (isalnum((unsigned char)p->src[p->pos]) ||
           p->src[p->pos] == '-' || p->src[p->pos] == '+' ||
           p->src[p->pos] == '.' || p->src[p->pos] == 'e' ||
           p->src[p->pos] == 'E'))
        p->pos++;
    size_t len = p->pos - (start - p->src);
    char *s = (char *)malloc(len + 1);
    memcpy(s, start, len);
    s[len] = '\0';
    JSONValue *v = new_value(JSON_NUMBER);
    v->u.num_str = s;
    return v;
}

static char *parse_string_raw(Parser *p) {
    /* p->src[p->pos] should be '"' */
    p->pos++; /* skip opening quote */
    size_t cap = 64;
    char *buf = (char *)malloc(cap);
    size_t len = 0;
    while (p->src[p->pos] && p->src[p->pos] != '"') {
        char c = p->src[p->pos];
        if (c == '\\') {
            p->pos++;
            char esc = p->src[p->pos];
            char out;
            switch (esc) {
                case '"': out = '"'; break;
                case '\\': out = '\\'; break;
                case '/': out = '/'; break;
                case 'b': out = '\b'; break;
                case 'f': out = '\f'; break;
                case 'n': out = '\n'; break;
                case 'r': out = '\r'; break;
                case 't': out = '\t'; break;
                case 'u': {
                    /* parse 4 hex digits */
                    char hex[5];
                    for (int i = 0; i < 4; i++) hex[i] = p->src[p->pos + 1 + i];
                    hex[4] = '\0';
                    p->pos += 4;
                    unsigned int cp = (unsigned int)strtoul(hex, NULL, 16);
                    /* encode as UTF-8 */
                    if (cp < 0x80) {
                        if (len + 1 >= cap) { cap *= 2; buf = realloc(buf, cap); }
                        buf[len++] = (char)cp;
                    } else if (cp < 0x800) {
                        if (len + 2 >= cap) { cap *= 2; buf = realloc(buf, cap); }
                        buf[len++] = (char)(0xC0 | (cp >> 6));
                        buf[len++] = (char)(0x80 | (cp & 0x3F));
                    } else {
                        if (len + 3 >= cap) { cap *= 2; buf = realloc(buf, cap); }
                        buf[len++] = (char)(0xE0 | (cp >> 12));
                        buf[len++] = (char)(0x80 | ((cp >> 6) & 0x3F));
                        buf[len++] = (char)(0x80 | (cp & 0x3F));
                    }
                    continue;
                }
                default: out = esc; break;
            }
            p->pos++;
            if (len + 1 >= cap) { cap *= 2; buf = realloc(buf, cap); }
            buf[len++] = out;
        } else {
            if (len + 1 >= cap) { cap *= 2; buf = realloc(buf, cap); }
            buf[len++] = c;
            p->pos++;
        }
    }
    p->pos++; /* skip closing quote */
    if (len + 1 >= cap) { cap = len + 1; buf = realloc(buf, cap); }
    buf[len] = '\0';
    return buf;
}

static JSONValue *parse_string(Parser *p) {
    char *s = parse_string_raw(p);
    JSONValue *v = new_value(JSON_STRING);
    v->u.str_val = s;
    return v;
}

static JSONValue *parse_array(Parser *p) {
    p->pos++; /* skip '[' */
    JSONValue *v = new_value(JSON_ARRAY);
    skip_ws(p);
    if (p->src[p->pos] == ']') {
        p->pos++;
        return v;
    }
    while (1) {
        skip_ws(p);
        JSONValue *item = parse_value(p);
        if (v->u.array.count >= v->u.array.cap) {
            v->u.array.cap = v->u.array.cap ? v->u.array.cap * 2 : 8;
            v->u.array.items = realloc(v->u.array.items, v->u.array.cap * sizeof(JSONValue *));
        }
        v->u.array.items[v->u.array.count++] = item;
        skip_ws(p);
        if (p->src[p->pos] == ',') {
            p->pos++;
        } else if (p->src[p->pos] == ']') {
            p->pos++;
            break;
        } else {
            break;
        }
    }
    return v;
}

static JSONValue *parse_object(Parser *p) {
    p->pos++; /* skip '{' */
    JSONValue *v = new_value(JSON_OBJECT);
    skip_ws(p);
    if (p->src[p->pos] == '}') {
        p->pos++;
        return v;
    }
    while (1) {
        skip_ws(p);
        char *key = parse_string_raw(p);
        skip_ws(p);
        p->pos++; /* skip ':' */
        skip_ws(p);
        JSONValue *val = parse_value(p);
        if (v->u.object.count >= v->u.object.cap) {
            v->u.object.cap = v->u.object.cap ? v->u.object.cap * 2 : 8;
            v->u.object.pairs = realloc(v->u.object.pairs, v->u.object.cap * sizeof(JSONPair));
        }
        v->u.object.pairs[v->u.object.count].key = key;
        v->u.object.pairs[v->u.object.count].value = val;
        v->u.object.count++;
        skip_ws(p);
        if (p->src[p->pos] == ',') {
            p->pos++;
        } else if (p->src[p->pos] == '}') {
            p->pos++;
            break;
        } else {
            break;
        }
    }
    return v;
}

static JSONValue *parse_value(Parser *p) {
    skip_ws(p);
    char c = p->src[p->pos];
    if (c == '{') return parse_object(p);
